#include "ContentPackManifest.hpp"
#include <functional>
namespace elysium::mod {
bool ContentPackResolver::add(PackManifest p,std::string&w){if(!p.id||p.nameSpace.empty()||p.schemas.empty()){w="invalid manifest";return false;}if(!packs_.emplace(p.id,std::move(p)).second){w="duplicate pack";return false;}return true;}
std::vector<PackId> ContentPackResolver::loadOrder(std::vector<Diagnostic>&d)const{std::vector<PackId> out;std::unordered_map<PackId,int> state;std::function<bool(PackId)> dfs=[&](PackId id){auto p=packs_.find(id);if(p==packs_.end()){d.push_back({id,"missing provider"});return false;}if(state[id]==1){d.push_back({id,"dependency cycle"});return false;}if(state[id]==2)return true;state[id]=1;auto deps=p->second.dependencies;std::sort(deps.begin(),deps.end(),[](auto&a,auto&b){return a.id<b.id;});for(auto dep:deps){auto q=packs_.find(dep.id);if(q==packs_.end()){d.push_back({id,"missing dependency"});return false;}bool schema=false;for(auto s:q->second.schemas)if(s>=dep.minSchema)schema=true;if(!schema){d.push_back({id,"incompatible dependency schema"});return false;}if(!dfs(dep.id))return false;}state[id]=2;out.push_back(id);return true;};std::vector<PackId> ids;for(auto&[id,_]:packs_)ids.push_back(id);std::sort(ids.begin(),ids.end());for(auto id:ids)if(!dfs(id))return {};return out;}
std::optional<ContentId> ContentPackResolver::remap(PackId p,ContentId id)const{auto i=packs_.find(p);if(i==packs_.end())return std::nullopt;for(auto r:i->second.remaps)if(r.from==id)return r.to;return id;}
bool ContentPackResolver::surfaceAllowed(PackId p,const std::string&s)const{auto i=packs_.find(p);if(i==packs_.end())return false;return std::find(i->second.extensionSurfaces.begin(),i->second.extensionSurfaces.end(),s)!=i->second.extensionSurfaces.end();}
}